import PrusaSlicer from './prusaslicer';
import Cura from './cura'
import SuperSlicer from './superslicer';
import ideaMaker from './ideaMaker';
import SlicerSpecificBase from './slicerbase';
import KiriMoto from './KiriMoto';
import OrcaSlicer from './orcaslicer';

//Orca forks rebrand themselves ("Snapmaker Orca", ...) but so far keep "Orca" in the generator
//name. Anchored to the "; generated by" comment so base64 thumbnail data further down the header
//cannot produce a false match.
const ORCA_GENERATOR = /^;\s*generated by\s+.*orca/im;

//Fallback for forks that drop "Orca" from the name entirely. These feature names are unique to the
//Orca/Bambu lineage among the slicers handled here - PrusaSlicer/SuperSlicer emit "External
//perimeter", Cura and ideaMaker "WALL-OUTER", Kiri:Moto "shells" - so a file using them is one
//OrcaSlicer's feature list can colour correctly regardless of who built the slicer.
//Case sensitive on purpose: Kiri:Moto emits a lowercase "sparse infill".
const ORCA_FEATURES = /^;\s*TYPE:\s*(?:Outer wall|Inner wall|Overhang wall|Internal solid infill|Top surface|Bottom surface|Prime tower)\s*$/m;

//;TYPE: markers sit past the header comments, thumbnails and start g-code, so this needs a far
//larger window than the generator line does. Only scanned when no generator matched.
const ORCA_FEATURE_SCAN_LIMIT = 262144;

export default class SlicerFacotry {
    static getSlicer(gcode) {
        if (!gcode) return null;
        let header = gcode.substring(0, 10000);
        if (header.includes('; generated by PrusaSlicer')) {
            return new PrusaSlicer();
        }
        else if (header.includes(';Generated with Cura_SteamEngine')) {
            return new Cura();
        }
        else if (header.includes('; generated by SuperSlicer')) {
            return new SuperSlicer();
        }
        else if (header.includes('Sliced by ideaMaker')) {
            return new ideaMaker();
        }
        else if (header.includes('; Generated by Kiri:Moto')) {
            return new KiriMoto();
        }
        else if (ORCA_GENERATOR.test(header)) {
            return new OrcaSlicer();
        }

        //Unrecognised generator - fall back to the shape of the feature comments before giving up.
        if (ORCA_FEATURES.test(gcode.substring(0, ORCA_FEATURE_SCAN_LIMIT))) {
            return new OrcaSlicer();
        }

        return new SlicerSpecificBase();
    }
}